# -*- coding: utf-8 -*-
"""From accusation to challenge, with calumny and cavil kept distinct."""
import json
from pathlib import Path
from lesson_authoring import entry as E
C=[['拉丁 calumnia','虚假指控、歪曲、中伤；通常联系 calvī / calvor“欺骗”']]
CH=C+[['拉丁 calumniārī；通俗拉丁相关形式 → 古法语 chalongier / chalengier、chalenge','指控、争辩、提出要求'],['中古英语 challenge','责问、反对 → 挑战、要求较量 → 困难任务']]
CA=C+[['法语 calomnie 与拉丁借入 → 英语 calumny','保留恶意虚假指控、中伤的意思']]
def A(h,a,b):return h+[[a,b]]
W=[
E('challenge','/ˈtʃælɪndʒ/','挑战；难题；质疑；要求较量','先是站出来说“这个说法或权利我不认可，请证明”，再走向“来比一比”，最后也能说一件考验能力的事。','拉丁 calumnia / calumniārī，经法语的指控、争辩词族进入；现代不能拆成 chal + lenge。',CH,'challenge a claim 是质疑主张；challenge someone to a race 是约人比试；a difficult challenge 是难题。早期来源有虚假指控义，但现代 challenge 完全可以是合理质疑，不能用词源给它强加恶意。','face a challenge；rise to the challenge；challenge an assumption；challenge someone to。','question 常是询问或怀疑；challenge 往往更主动地要求对方说明、证明或接受考验。它也不等于不可能完成的任务。',('The study challenges a widely accepted assumption.','这项研究对一个广为接受的假设提出了质疑。'),('Learning to work with a new team was her biggest challenge.','学会与新团队合作，是她最大的挑战。'),('He challenged his friend to a game of chess.','他向朋友发出挑战，要下一盘国际象棋。'),sources=['https://www.etymonline.com/word/challenge','https://en.wiktionary.org/wiki/challenge#English']),
E('challenging','/ˈtʃælɪndʒɪŋ/','有挑战性的；困难而考验能力的；带质问意味的','任务向你的能力发出挑战，逼你多想一步、多做一点；它可能难，却仍有值得尝试的意味。','challenge + -ing，分词成为形容词。',A(CH,'英语 challenge → challenging','考验、挑战 → 考验能力的'),'a challenging task 可能困难但有价值；a challenging question 也可能是追问、质疑式的问题。比 difficult 更容易突出需要努力与发挥能力，但不是处处都褒义。','a challenging role；a challenging task；intellectually challenging。','challenging 描述任务给人的挑战；challenged 是受挑战、被质疑等状态，两者方向不同。',('The new role is challenging, but she enjoys learning.','新岗位很有挑战性，但她喜欢学习。'),('The interviewer asked a challenging question about the evidence.','采访者针对证据提出了一个颇具质疑意味的问题。')),
E('challenger','英 /ˈtʃælɪndʒə/；美 /ˈtʃælɪndʒər/','挑战者；争夺现有地位的人','一个人已经坐在冠军或领先者的位置，另一个人走上来争这个位置，就是 challenger。','中古英语 chalengere / chalengeour 等；兼有法语人物名词和英语 challenge + -er 的形成路线。',[C[0],['古法语 chalengeor；中古英语 challenge + -er → challenger','提出争议、主张或挑战的人'],['现代英语 challenger','向现有领先者或权力位置发起挑战的人']],'常用于体育冠军争夺、选举或市场竞争。a challenger brand 是挑战既有强者的品牌，不代表它已经超过领先者。','a title challenger；a serious challenger；a challenger brand。','competitor 是一般竞争者；challenger 常把一方描写成原有地位的挑战者，与 champion、incumbent 等相对。',('The challenger won the opening round against the champion.','挑战者在与冠军的较量中赢下了第一回合。'),('The small company emerged as a serious challenger in the market.','这家小公司逐渐成为市场中不可忽视的挑战者。'),sources=['https://en.wiktionary.org/wiki/challenger#English']),
E('unchallenged','/ʌnˈtʃælɪndʒd/','未被质疑的；未遇挑战的；无人阻挡的','一个说法摆在那里，却没人站出来反对；或者一个人继续占据地位，始终没人挑战。','un- 不 + challenged；challenge 的过去分词加否定。',A(CH,'英语 challenged；un- + challenged → unchallenged','受到质疑、挑战 → 未受质疑、挑战'),'go unchallenged 是未受到质疑；remain unchallenged 是仍无人挑战。未被反驳只描述当时的争论状态，并不自动等于已获证明。','go unchallenged；remain unchallenged；an unchallenged claim。','undefeated 是没有被打败；unchallenged 可能根本没人来比，两种情况不同。',('The claim went unchallenged during the meeting.','会议期间，没有人对这项主张提出质疑。'),('For years, the company’s position remained unchallenged.','多年来，这家公司的地位一直无人挑战。')),
E('calumny','/ˈkæləmni/','诽谤；恶意中伤；虚假指控〔正式〕','把假的坏事扣到某个人头上，让别人看低他；重点在损害名誉的虚假说法。','拉丁 calumnia，经法语或拉丁借入；与 challenge 的较早来源相同，但保留了中伤义。',CA,'可作不可数名词说一类中伤，也可用 a calumny、calumnies 指一项项虚假指控。是很正式、评价强烈的词，通常不是一般不同意见。','spread calumny；a malicious calumny；the target of calumny。','criticism 可以有根据；calumny 指虚假的中伤。与 challenge 同源，不代表现代意思仍相同。',('The biography shows how calumny damaged his reputation.','传记展示了恶意中伤如何损害他的名誉。'),('She rejected the accusation as a calumny.','她斥责这项指控是诽谤。'),sources=['https://www.etymonline.com/word/calumny']),
E('calumnious','/kəˈlʌmniəs/','诽谤性的；中伤人的〔正式〕','一句话或一份材料带着 calumny 的性质：靠虚假的不利说法伤害别人名誉。','后期拉丁 calumniōsus，或经法语 calomnieux 借入；对应 calumnia + -ōsus。',[C[0],['后期拉丁 calumniōsus；法语 calomnieux → 英语 calumnious','充满中伤的 → 诽谤性的']],'常修饰 accusations、reports、statements。calumny 重音在第一音节，calumnious 移到第二音节，元音也相应改变。','calumnious allegations；a calumnious statement；calumnious reports。','calumnious 指中伤内容的性质；challenging 可以只是有挑战性，不能因为同源就互换。',('The article repeated several calumnious allegations.','文章重复了几项诽谤性的指控。'),('The speaker denied making any calumnious statement.','发言者否认说过任何中伤他人的话。'),sources=['https://www.merriam-webster.com/dictionary/calumnious']),
E('calumniate','/kəˈlʌmnieɪt/','诽谤；恶意中伤〔正式〕','把 calumny 从“中伤的话”变成“去中伤某人”这个动作：传播不实指控，使人名誉受损。','拉丁 calumniātus，calumniārī“虚假指控”的分词形式，借入英语作动词。',[C[0],['拉丁 calumniārī → calumniātus → 英语 calumniate','作虚假指控 → 诽谤、中伤']],'直接接对象 calumniate someone。这个词较书面，日常 slander 或 smear 更常见；它并非“严厉批评”的漂亮替换词，而包含虚假中伤的指控。','calumniate an opponent；calumniate someone’s character。','calumniate 的词尾 /eɪt/ 是动词读法；calumnious 的 /əs/ 是形容词结尾。calumny 则是名词。',('The pamphlet attempted to calumniate a political opponent.','小册子试图诽谤一名政治对手。'),('The essay asks why the writer’s enemies sought to calumniate him.','文章探讨了为什么那位作家的敌人试图中伤他。'),sources=['https://www.etymonline.com/word/calumniate','https://dictionary.cambridge.org/pronunciation/english/calumniate']),
E('cavil','/ˈkævəl/','吹毛求疵；挑小毛病；无谓异议','抓住不重要的小处反复挑刺，像是为了反对而反对，反而避开真正关键的问题。','拉丁 cavilla“嘲弄”→ cavillārī → 法语 caviller → 英语 cavil；传统词源常把它联系到 calumnia 的较远词族。',[['拉丁 cavilla → cavillārī','嘲弄、讥刺 → 挑剔地争辩'],['法语 caviller → 英语 cavil','嘲弄、争辩 → 吹毛求疵']],'常用 cavil at 或 cavil about。也可作名词 a cavil，指一个无谓异议；现代更常遇到动词。它含说话者对这种挑剔的不赞同。','cavil at details；cavil about wording；a minor cavil。','challenge 可以是合理质疑；cavil 把异议评价为琐碎或无理。它也不是 cavalry“骑兵”的缩写。',('Rather than cavil at the wording, let us discuss the main argument.','与其在措辞上吹毛求疵，不如讨论主要论点。'),('She accepted the result without a cavil.','她接受了结果，没有提出无谓的异议。'),sources=['https://www.etymonline.com/word/cavil']),
]
ROOT=dict(id='C0159',meaning='指控、争辩；中伤与挑战',core='CALUMN = FALSE ACCUSATION; CHALLENGE',image='想象有人站出来说：“你的说法不成立，你得回应。”这幅争辩画面后来可以变成正当质疑和挑战；另一条线则保留把坏话硬扣到别人头上的中伤。',intro='拉丁 calumnia 的核心是虚假指控、歪曲，通常联系 calvī / calvor“欺骗”。经法语演变，challenge 的意义逐渐扩大到质疑、较量和考验；另一次借入形成 calumny，保留中伤义。cavil 接拉丁 cavilla 的嘲弄支线，不能写成英语 calumny 直接变出来。',forms='challenge 与 calumny 是同源而形貌不同的借词。calumny /ˈkæləmni/、calumnious /kəˈlʌmniəs/、calumniate /kəˈlʌmnieɪt/ 重音并不固定在同一位置，最好整词读。',branches=[['现代常用的质疑与考验','challenge, challenging, challenger, unchallenged'],['保留虚假中伤义','calumny, calumnious, calumniate'],['嘲弄、琐碎挑剔的旁支','cavil']],contrasts='合理 challenge 不是 calumny。词源可以解释历史联系，却不能把早期“虚假指控”强加给今天所有 challenge。cavil 强调异议琐碎无理，与严肃检验论证也不同。',practice='A strong argument should survive a fair challenge. We can question a claim without spreading calumny or cavilling at every minor detail.\n\n有力的论证应该经得住合理质疑。我们可以检验一项主张，而不散布中伤，也不在每个小细节上吹毛求疵。',words=[w['word'] for w in W])
if __name__=='__main__':
 t=Path(__file__).resolve().parents[1]/'.cache/batch200/drafts/root'
 for k,v in [('roots',[ROOT]),('words',W)]: (t/f'{k}_batch200_root_calv.json').write_text(json.dumps(v,ensure_ascii=False,indent=2))
 print(len(W),'individually authored words')
